 majorPent:{name:'Major pentatonic',intervals:[0,2,4,7,9],degrees:['1','2','3','5','6'],color:9,feel:'Open, melodic, sweet',about:'Major without its 4th and 7th. Its five notes are useful for clear, singable phrases.',fit:'A starting point for country, folk, pop and major blues. In a blues, watch the major 3rd when the harmony moves to the IV chord.',chord:'',genres:['Pop & folk','Blues'],practice:'Sing a short phrase before finding it on the guitar. Finish on 1, 3 or 5 over the tonic major chord.'},
