function progName(p,i){const base=SCALES[p.scale],letters=spelling(state.root,base);return letters[base.degrees.findIndex(d=>Number(d.replace(/[^0-9]/g,''))===p.degrees[i])]+p.seq[i][1];}
function chordMidi(pc,q){const intervals=q==='m'?[0,3,7]:q==='7'?[0,4,7,10]:q==='m7'?[0,3,7,10]:q==='maj7'?[0,4,7,11]:[0,4,7];return intervals.map(x=>48+mod(pc)+x)}
function progressionsView(){const p=PROGS[state.progression];return intro()+`<div class="progression-layout"><div class="progression-picker" aria-label="Choose progression">${PROGS.map((v,i)=>`<button data-progression="${i}" class="${i===state.progression?'active':''}" aria-pressed="${i===state.progression}"><strong>${v.name}</strong><small>${v.formula}</small></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><span class="eyebrow chapter">${p.genre}</span><h2 style="margin-top:8px">${p.name}</h2><p>${p.formula}</p></div>${rootSelect()}</div><p>${p.why}</p><div class="chord-sequence">${p.seq.map((v,i)=>`<button class="chord" data-prog-chord="${i}" aria-label="Hear ${progName(p,i)}, bar ${i+1}"><span class="bar-number">${i+1}</span><span class="roman">${p.nums[i]}</span><strong>${progName(p,i)}</strong><small>4 beats</small></button>`).join('')}</div><div class="progress-controls"><button id="play-progression" class="btn primary">▶ Play loop</button><label for="tempo">Tempo <b id="tempo-value">${state.bpm}</b> BPM</label><input id="tempo" type="range" min="50" max="140" step="5" value="${state.bpm}" aria-label="Tempo in beats per minute"></div><div id="audio-status" class="audio-note" role="status">One bar per tile · straight quarter notes · click a chord to hear it</div><div class="insight"><h3>What can I play over it?</h3><p>${p.tip}</p><button class="text-link" data-explore="${p.scale}" style="margin-top:12px">Open ${rootName()} ${SCALES[p.scale].name} →</button></div>${p.songs.length?`<div class="song"><span class="eyebrow">HEAR IT IN A SONG</span>${p.songs.map(song=>`<h3 style="margin-top:12px">${song[0]} <span style="font-weight:400;color:var(--muted)">— ${song[1]}</span></h3><p>${song[2]}</p><a href="${song[3]}" target="_blank" rel="noopener noreferrer">Song lesson / theory reference ↗</a>`).join('')}</div>`:`<div class="song"><span class="eyebrow">PRACTICE FRAMEWORK</span><p>This is a generic teaching progression, not a transcription of a particular recording.</p></div>`}<p class="tiny" style="margin-top:20px">Playback demonstrates the harmony, not the song’s melody, arrangement or exact rhythm.</p></section></div>`;}
function modesView(){const keys=['ionian','dorian','phrygian','lydian','mixolydian','aeolian','locrian'];const genres=['All modes','Blues','Funk & soul','Rock & metal','Pop & folk','Jazz','Ambient'];const selected=keys.filter(k=>state.genre==='All modes'||SCALES[k].genres.includes(state.genre));return intro()+`<section class="panel"><h2>A mode is a sound around a home note.</h2><p style="margin:12px 0">C major and D Dorian share the same notes. The difference is the tonal centre: the bass, chords and phrase endings make C or D feel like home. Simply starting a C-major run on D does not necessarily make the music Dorian.</p><div class="callout"><p><strong>Try parallel modes:</strong> compare A Ionian, A Dorian and A Mixolydian over an A drone. Keeping the root fixed makes the changed intervals much easier to hear.</p></div><p class="tiny">The seven modes below come from the major scale. Their formulas are measured against a major scale with the same root.</p></section><div class="panel-head"><h2>Find a starting sound</h2>${rootSelect()}</div><div class="genre-row" aria-label="Genre suggestions">${genres.map(g=>`<button data-genre="${g}" class="${g===state.genre?'selected':''}" aria-pressed="${g===state.genre}">${g}</button>`).join('')}</div><p class="tiny">Genres suggest possibilities, not rules. Match the actual chord tones before choosing a mode.</p><div class="mode-cards">${selected.map(k=>{const s=SCALES[k];return `<article class="card"><span class="eyebrow">MODE ${keys.indexOf(k)+1} · ${s.feel.toUpperCase()}</span><h2>${s.name}</h2><div class="formula">${s.degrees.join(' · ')}</div><p>${s.about}</p><p><strong style="color:var(--text)">Try it over ${rootName()}${s.chord}.</strong> ${s.fit}</p><button class="btn" data-explore="${k}">Explore ${rootName()} ${s.name} →</button></article>`}).join('')}</div><section class="panel" style="margin-top:22px"><h2>Blues: a practical place to begin</h2><p style="margin-top:12px">Over A7, A Mixolydian gives you A B C♯ D E F♯ G. Its A–C♯–E–G notes outline the chord. Over D7 and E7, switching to their own Mixolydian scales follows the changing chord tones.</p><p>A minor pentatonic adds a different blues colour: its C natural rubs against A7’s C♯. Blues players deliberately work between these sounds. Use phrasing and your ear, not just a fixed fingering.</p><button class="btn primary" data-blues="true">Try a blues in A →</button><p class="sources">Further reading: <a href="https://www.fretjam.com/mixolydian-blues.html" target="_blank" rel="noopener noreferrer">Fretjam — Mixolydian over blues</a> · <a href="https://www.latinguitarmastery.com/theory/the-mixolydian-scale/" target="_blank" rel="noopener noreferrer">Latin Guitar Mastery — Mixolydian</a></p></section>`;}

function jamTheory(bar=state.currentJamBar){const p=activeJamProgression(),i=bar%p.seq.length,[offset,q]=p.seq[i],chordRoot=mod(state.root+offset);let scaleKey=p.scale,scaleRoot=state.root;if(state.jamScale==='follow'){scaleRoot=chordRoot;scaleKey=q==='7'?'mixolydian':q==='m'?'aeolian':q==='m7'?'dorian':'ionian';}else if(state.jamScale==='minorPent'){scaleKey='minorPent';}else if(state.jamScale==='blues'){scaleKey='blues';}const intervals=q==='m'?[0,3,7]:q==='7'?[0,4,7,10]:q==='m7'?[0,3,7,10]:q==='maj7'?[0,4,7,11]:[0,4,7];return {p,i,q,chordRoot,scaleRoot,scaleKey,scale:SCALES[scaleKey],chordPcs:intervals.map(x=>mod(chordRoot+x))};}
function simpleName(pc){return ROOTS.find(x=>x[1]===mod(pc))[0]}
function jamFretboard(){const width=960,left=58,cw=(width-left-20)/13;let out=`<svg class="fretboard jam-fretboard" viewBox="0 0 960 280" aria-label="Live fretboard; high E at top. Scale notes and current chord tones change as the loop plays." role="img"><rect x="${left}" y="29" width="${width-left-20}" height="213" rx="5" fill="#171b18"/>`;for(let f=0;f<=12;f++){const x=left+f*cw;out+=`<line x1="${x}" y1="30" x2="${x}" y2="242" stroke="${f===1?'#a3aa98':'#3e473c'}" stroke-width="${f===1?4:2}"/><text x="${x+cw/2}" y="268" text-anchor="middle" fill="#9ca895" font-size="14">${f===0?'open':f}</text>`;if([3,5,7,9,12].includes(f))out+=`<circle cx="${x+cw/2}" cy="136" r="5" fill="#3e4939"/>`;}for(let row=0;row<6;row++){const si=5-row,y=40+row*38;out+=`<text x="25" y="${y+5}" text-anchor="middle" fill="#b5c0ad" font-size="16">${STRINGS[si]}</text><line x1="${left}" y1="${y}" x2="940" y2="${y}" stroke="#6b7465" stroke-width="${.8+row*.3}"/>`;for(let f=0;f<=12;f++){const midi=OPEN[si]+f,pc=mod(midi),x=left+(f+.5)*cw;out+=`<g class="jam-note outside" data-jam-pc="${pc}"><circle cx="${x}" cy="${y}" r="14"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="12" font-weight="600">${simpleName(pc)}</text></g>`;}}return out+'</svg>';}
function jamView(){const studio=state.jamMode==='studio',p=activeJamProgression(),t=jamTheory(0);state.currentJamBar=0;return intro()+`<section class="panel jam-console"><div class="controls jam-controls"><div class="field"><label for="jam-mode">BACKING TYPE</label><select id="jam-mode"><option value="studio" ${studio?'selected':''}>Arranged tracks</option><option value="flexible" ${!studio?'selected':''}>Transposable loops</option></select></div>${studio?`<div class="field wide"><label for="studio-track">TRACK</label><select id="studio-track">${BACKING_TRACKS.map((v,i)=>`<option value="${i}" ${i===state.studioTrack?'selected':''}>${v.name} · ${v.style}</option>`).join('')}</select></div><span class="badge">${p.key} · ${p.bpm} BPM</span><a class="btn small" href="${p.stems.mix}" download>↓ Download track</a>`:`<div class="field wide"><label for="jam-progression">BACKING LOOP</label><select id="jam-progression">${PROGS.map((v,i)=>`<option value="${i}" ${i===state.jamProgression?'selected':''}>${v.name}</option>`).join('')}</select></div>${rootSelect()}<div class="field"><label for="jam-groove">GROOVE</label><select id="jam-groove"><option value="straight" ${state.jamGroove==='straight'?'selected':''}>Straight 8ths</option><option value="shuffle" ${state.jamGroove==='shuffle'?'selected':''}>Blues shuffle</option></select></div><div class="field"><label for="jam-tone">GUITAR SOUND</label><select id="jam-tone"><option value="warm" ${state.jamTone==='warm'?'selected':''}>Warm crunch</option><option value="clean" ${state.jamTone==='clean'?'selected':''}>Clean electric</option><option value="muted" ${state.jamTone==='muted'?'selected':''}>Muted rhythm</option></select></div>`}</div>${studio?`<p>${p.description}</p><p class="tiny">Original arrangement · fixed key and tempo · four-click count-in · continuous loop</p>${studioMixControls()}`:''}<div class="jam-transport"><div><span class="eyebrow">NOW PLAYING</span><h2 id="jam-now">Ready · ${progName(p,0)}</h2><p id="jam-scale-name">Suggested notes: ${simpleName(t.scaleRoot)} ${t.scale.name}</p></div><button id="start-jam" class="btn primary jam-play">▶ Start jam</button></div><div class="jam-bars" aria-label="Progression bars">${p.seq.map((v,i)=>`<div class="jam-bar ${i===0?'active':''}" data-jam-bar="${i}"><span>${i+1}</span><b>${progName(p,i)}</b><small>${p.nums[i]}</small></div>`).join('')}</div><div class="progress-controls jam-options">${studio?`<span class="tiny">${p.style} · ${p.seq.length} bars</span>`:`<label for="tempo">Tempo <b id="tempo-value">${state.bpm}</b> BPM</label><input id="tempo" type="range" min="50" max="140" step="5" value="${state.bpm}" aria-label="Jam tempo in beats per minute">`}<label class="check"><input id="jam-drums" type="checkbox" ${state.jamDrums?'checked':''}> Drums</label><label class="check"><input id="jam-bass" type="checkbox" ${state.jamBass?'checked':''}> Bass</label><span class="tiny push">CC0 sampled guitar, bass &amp; drums</span></div><div id="audio-status" class="audio-note" role="status">Press start, then play a short phrase. The fretboard will follow each chord.</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">LIVE NOTE GUIDE</span><h2 style="margin-top:8px">Follow the chord tones</h2></div><div class="field wide"><label for="jam-scale">NOTE STRATEGY</label><select id="jam-scale"><option value="follow" ${state.jamScale==='follow'?'selected':''}>Follow each chord</option><option value="parent" ${state.jamScale==='parent'?'selected':''}>${SCALES[p.scale].name} of the key</option><option value="minorPent" ${state.jamScale==='minorPent'?'selected':''}>Tonic minor pentatonic</option><option value="blues" ${state.jamScale==='blues'?'selected':''}>Tonic blues scale</option></select></div></div><div class="fret-scroll">${jamFretboard()}</div><div class="legend"><span><i class="dot"></i>Current chord root</span><span><i class="dot color"></i>Other chord tone</span><span><i class="dot other"></i>Scale note</span><span class="hint">Chord tones are safe places to land</span></div><div class="callout" id="jam-tip"><p><strong>First pass:</strong> play only the highlighted chord roots. <strong>Second pass:</strong> add one other chord tone. <strong>Third pass:</strong> connect them with scale notes.</p></div></section><div class="two-col"><section class="panel"><span class="eyebrow">A SIMPLE SOLOING RULE</span><h2 style="margin-top:8px">Follow the harmony without chasing every note.</h2><p style="margin-top:12px">You can use one broad scale across a progression, then make the line sound connected by landing on a note from the current chord when it changes. The live guide separates those chord tones from the surrounding scale.</p><p>Over the 12-bar blues, “Follow each chord” switches Mixolydian with I7, IV7 and V7. “Tonic blues scale” keeps one familiar shape and lets its tensions rub against the changing chords.</p></section><section class="panel practice"><span class="eyebrow">FOUR-BAR CHALLENGE</span><h2 style="margin-top:8px">Leave as much space as you play.</h2><ol><li>Play a two-beat phrase.</li><li>Rest for two beats.</li><li>Answer it in the next bar.</li><li>End the fourth bar on a highlighted chord tone.</li></ol><p class="tiny">Each arrangement leaves space for your lead guitar. Lower the rhythm guitar or drums to practise the part you want to hear more clearly.</p></section></div>`;}
let audio=null,oscillators=[],timers=[],droneNodes=[],playing=false,audioPending=false;
function transportActive(active){const b=document.getElementById('stop-all');if(b)b.disabled=!active;}
async function getAudio({feedback=true,instruments=null,loadingMessage=null}={}){
 const needed=instruments||(['licks','legends'].includes(state.view)?lickOptions.backing?['guitar','bass']:['guitar']:state.view==='jam'?['guitar',...(state.jamBass?['bass']:[]),...(state.jamDrums?['drums']:[])]:['guitar']);
 const generation=lickPlaybackGeneration,C=window.AudioContext||window.webkitAudioContext;
 if(!C){status('Audio is not supported in this browser. You can still use all diagrams and tabs.');return null;}
 if(!audio){audio=new C();audio.onstatechange=()=>{if(audio.state!=='running'&&playing){stopAudio();status('Audio paused. Tap Play to resume.');}};}
 // Resume and prime the output while still inside the original tap gesture.
 const ctx=audio,resume=ctx.resume();
 const primer=ctx.createBufferSource();primer.buffer=ctx.createBuffer(1,1,ctx.sampleRate);primer.connect(ctx.destination);primer.onended=()=>primer.disconnect();primer.start();
 if(feedback){audioPending=true;transportActive(true);status(loadingMessage||(sampleLoadPromise?'Preparing playback…':'Loading instrument sounds…'));}
 try{await resume;await loadGuitarSamples(ctx,needed);
  if(generation!==lickPlaybackGeneration||document.hidden)return null;
  if(ctx.state!=='running')await ctx.resume();
  if(generation!==lickPlaybackGeneration||document.hidden)return null;
  if(ctx.state!=='running')throw Error('Audio output is paused');
  if(feedback)audioPending=false;return ctx;
 }catch(error){if(generation!==lickPlaybackGeneration)return null;throw error;}
}
function keepSource(source,...nodes){oscillators.push(source);source.onended=()=>{source.disconnect();nodes.forEach(n=>n.disconnect());oscillators=oscillators.filter(x=>x!==source);if(!playing&&!audioPending&&!oscillators.length&&!droneNodes.length)transportActive(false)}}
function tone(midi,when,duration=.75,volume=.11,preset=state.jamTone){sampleVoice(audio,midi,when,preset==='muted'?Math.min(duration,.22):duration,volume*2,preset,true);}
function drum(type,when,volume=.08){sampledDrum(audio,type,when,volume,true,volume>.05?110:55);}
function stopAudio(){stopRhythm();resetSampleAudio(audio);stopLickPlayback();stopBackingPlayback();lickPlaybackGeneration++;resetLickUI();timers.forEach(clearTimeout);timers=[];[...oscillators,...droneNodes].forEach(o=>{try{o.stop()}catch{}});oscillators=[];droneNodes=[];playing=false;audioPending=false;transportActive(false);document.querySelectorAll('[data-prog-chord],[data-jam-bar]').forEach(e=>e.classList.remove('active'));const b=document.getElementById('play-progression');if(b)b.textContent='▶ Play loop';const j=document.getElementById('start-jam');if(j)j.textContent='▶ Start jam';const d=document.getElementById('drone');if(d)d.textContent=`▶ Start ${rootName()} drone`;const s=document.getElementById('play-scale');if(s)s.textContent='▶ Hear scale';}
function status(t){const e=document.getElementById('audio-status');if(e)e.textContent=t;document.getElementById('announcement').textContent=t;const transport=document.getElementById('transport-status');if(transport)transport.textContent=t;}
async function hearNote(midi){stopAudio();const a=await getAudio();if(a){tone(midi,a.currentTime);status(`${noteName(midi)} · ${Math.round(440*Math.pow(2,(midi-69)/12))} Hz`);}}
async function playScale(){if(playing||audioPending){stopAudio();status('Playback stopped.');return;}stopAudio();const a=await getAudio();if(!a)return;playing=true;document.getElementById('play-scale').textContent='■ Stop scale';const path=scalePath(),seq=[...path,...path.slice(0,-1).reverse()],step=.28;seq.forEach((n,i)=>tone(n.midi,a.currentTime+i*step,.35,.12));status('Playing two octaves up and down — the ascending part matches the tab.');timers.push(setTimeout(()=>{stopAudio();status('Now try the pattern on your guitar.');},seq.length*step*1000+200));}
async function drone(){if(droneNodes.length||audioPending){stopAudio();status('Drone stopped.');return;}stopAudio();const a=await getAudio();if(!a)return;[state.root+36,state.root+48].forEach((m,i)=>{const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=440*Math.pow(2,(m-69)/12);g.gain.value=i?.035:.065;o.connect(g);g.connect(a.destination);o.start();o.onended=()=>{o.disconnect();g.disconnect()};droneNodes.push(o);});document.getElementById('drone').textContent='■ Stop drone';status(`Sustaining ${rootName()}. Play a phrase and return to the root.`);}
async function hearChord(midis){stopAudio();const a=await getAudio();if(a)midis.forEach((m,i)=>tone(m,a.currentTime+i*.025,1.1,.07));}
async function loopProgression(){if(playing||audioPending){stopAudio();status('Loop stopped.');return;}stopAudio();const a=await getAudio();if(!a)return;playing=true;document.getElementById('play-progression').textContent='■ Stop loop';let beat=0;const p=PROGS[state.progression];function tick(){if(!playing)return;const bar=Math.floor(beat/4)%p.seq.length,[offset,q]=p.seq[bar];chordMidi(state.root+offset,q).forEach((m,i)=>tone(m,a.currentTime+i*.014,.5,.045));if(beat%4===0){document.querySelectorAll('[data-prog-chord]').forEach((e,i)=>e.classList.toggle('active',i===bar));status(`Bar ${bar+1} of ${p.seq.length} · ${progName(p,bar)}`);}beat++;timers=[setTimeout(tick,60000/state.bpm)];}tick();}
function jamVoicing(root,q){const intervals=q==='m'?[0,3,7,12]:q==='7'?[0,4,7,10]:q==='m7'?[0,3,7,10]:q==='maj7'?[0,4,7,11]:[0,4,7,12];let base=45+mod(root-9);while(base>56)base-=12;return intervals.map(x=>base+x);}
function updateJamUI(bar){state.currentJamBar=bar;const t=jamTheory(bar),chordName=progName(t.p,t.i),scalePcs=t.scale.intervals.map(x=>mod(t.scaleRoot+x));document.querySelectorAll('[data-jam-bar]').forEach((e,i)=>e.classList.toggle('active',i===bar));document.querySelectorAll('.jam-note').forEach(e=>{const pc=Number(e.dataset.jamPc),isRoot=pc===t.chordRoot,isChord=t.chordPcs.includes(pc),isScale=scalePcs.includes(pc);e.classList.toggle('chord-root',isRoot);e.classList.toggle('chord-tone',!isRoot&&isChord);e.classList.toggle('scale-tone',!isChord&&isScale);e.classList.toggle('outside',!isChord&&!isScale);});const now=document.getElementById('jam-now'),scale=document.getElementById('jam-scale-name');if(now)now.textContent=`Bar ${bar+1} · ${chordName}`;if(scale)scale.textContent=`Suggested notes: ${simpleName(t.scaleRoot)} ${t.scale.name} · land on ${t.chordPcs.map(simpleName).join(', ')}`;}
async function startJam(){if(state.jamMode==='studio')return startStudioBacking();if(playing||audioPending){stopAudio();updateJamUI(0);status('Jam stopped.');return;}stopAudio();const a=await getAudio();if(!a)return;playing=true;document.getElementById('start-jam').textContent='■ Stop jam';let beat=0;const p=PROGS[state.jamProgression];function tick(){if(!playing)return;const bar=Math.floor(beat/4)%p.seq.length,beatInBar=beat%4,[offset,q]=p.seq[bar],root=mod(state.root+offset),now=a.currentTime+.018,seconds=60/state.bpm;if(beatInBar===0)updateJamUI(bar);if(beatInBar===0||beatInBar===2)jamVoicing(root,q).forEach((m,i)=>tone(m,now+i*.024,beatInBar===0?1.2:.7,beatInBar===0?.052:.035,state.jamTone));if(state.jamGroove==='shuffle'&&(beatInBar===1||beatInBar===3))jamVoicing(root,q).slice(1).forEach((m,i)=>tone(m,now+seconds*.64+i*.018,.18,.018,'muted'));if(state.jamBass){const bass=24+root+(beatInBar%2?7:0);tone(bass,now,.42,.065,'bass');}if(state.jamDrums){drum(beatInBar===0||beatInBar===2?'kick':'snare',now,beatInBar===0?.075:.055);drum('hat',now,.025);if(state.jamGroove==='shuffle')drum('hat',now+seconds*.66,.017);}beat++;timers=[setTimeout(tick,seconds*1000)];}tick();status(`${p.name} started. The note guide follows the active bar.`);}
function navigate(view){if(!VIEWS[view])return;stopAudio();state.view=view;if(view==='jam'&&state.jamMode==='studio')state.root=BACKING_TRACKS[state.studioTrack].root;history.replaceState(null,'','#'+view);render();}
function render(){document.getElementById('main').innerHTML=({scales:scalesView,harmony:harmonyView,progressions:progressionsView,modes:modesView,jam:jamView,licks:licksView,rhythm:rhythmView,legends:legendsView,releases:releasesView})[state.view]();document.getElementById('breadcrumb').textContent=VIEWS[state.view][1];document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(state.view==='jam')updateJamUI(0);const nav=document.querySelector('.sidebar nav'),active=document.querySelector('.nav.active');if(nav&&active&&window.innerWidth<=760)nav.scrollLeft=Math.max(0,active.offsetLeft-nav.offsetLeft-(nav.clientWidth-active.offsetWidth)/2);}
function change(field,value){stopAudio();state[field]=value;render();}
document.addEventListener('change',e=>{const id=e.target.id;if(id==='jam-mode'){stopAudio();state.jamMode=e.target.value;if(state.jamMode==='studio')state.root=BACKING_TRACKS[state.studioTrack].root;render();return;}if(id==='studio-track'){stopAudio();state.studioTrack=Number(e.target.value);state.root=BACKING_TRACKS[state.studioTrack].root;render();return;}if(state.jamMode==='studio'&&['jam-drums','jam-bass'].includes(id)){state[id==='jam-drums'?'jamDrums':'jamBass']=e.target.checked;applyStudioMix();return;}if(id==='root')change('root',Number(e.target.value));if(['scale','position','harmony'].includes(id))change(id,e.target.value);if(id==='jam-progression')change('jamProgression',Number(e.target.value));if(id==='jam-groove')change('jamGroove',e.target.value);if(id==='jam-tone')change('jamTone',e.target.value);if(id==='jam-scale')change('jamScale',e.target.value);if(id==='jam-drums')change('jamDrums',e.target.checked);if(id==='jam-bass')change('jamBass',e.target.checked);});
document.addEventListener('input',e=>{if(e.target.id==='tempo'){state.bpm=Number(e.target.value);document.getElementById('tempo-value').textContent=state.bpm;}});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-midi]');if(!b)return;if(b.id==='stop-all'){stopAudio();status('Playback stopped.');}if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.labels)change('labels',b.dataset.labels);if(b.dataset.chord!==undefined)change('chord',Number(b.dataset.chord));if(b.dataset.progression!==undefined)change('progression',Number(b.dataset.progression));if(b.dataset.genre)change('genre',b.dataset.genre);if(b.dataset.explore){state.scale=b.dataset.explore;navigate('scales');}if(b.dataset.blues){state.root=9;state.progression=3;navigate('progressions');}if(b.dataset.midi)hearNote(Number(b.dataset.midi)).catch(audioError);if(b.dataset.progChord!==undefined){const p=PROGS[state.progression],i=Number(b.dataset.progChord),[v,q]=p.seq[i];hearChord(chordMidi(state.root+v,q)).catch(audioError);}if(b.id==='play-scale')playScale().catch(audioError);if(b.id==='drone')drone().catch(audioError);if(b.id==='hear-chord')hearChord(harmonyChords()[state.chord].midi).catch(audioError);if(b.id==='play-progression')loopProgression().catch(audioError);if(b.id==='start-jam')startJam().catch(audioError);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-midi]')){e.preventDefault();hearNote(Number(e.target.dataset.midi)).catch(audioError)}});
function audioError(){stopAudio();status('Audio could not start. Try tapping play again and check your device volume.');}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));window.addEventListener('pagehide',stopAudio);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});
if(VIEWS[location.hash.slice(1)])state.view=location.hash.slice(1);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_scale_explorer',title:'Explore a guitar scale',description:'Select a root and scale and show its notes, fretboard and two-octave tab. Does not start audio.',inputSchema:{type:'object',properties:{root:{type:'string',enum:ROOTS.map(x=>x[0])},scale:{type:'string',enum:Object.keys(SCALES)}},required:['root','scale'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['root','scale'].includes(k))||!Object.hasOwn(SCALES,input.scale)||!ROOTS.some(x=>x[0]===input.root))throw new Error('Choose a supported root and scale.');state.root=ROOTS.find(x=>x[0]===input.root)[1];state.scale=input.scale;navigate('scales');return {root:rootName(),scale:SCALES[state.scale].name,notes:spelling(state.root,SCALES[state.scale]),tab:scalePath().map(x=>({string:6-x.string,fret:x.fret}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
